INSERT INTO pests_diseases (crop_id, name, symptoms, prevention, image_url) VALUES
                                                                                (1, '稻瘟病', '叶部产生菱形病斑，中心灰白边缘褐色；穗颈受害变褐腐烂。', '选用三环唑、稻瘟灵或春雷霉素喷雾。', 'images/1.jpg'),
                                                                                (1, '水稻纹枯病', '叶鞘出现云纹状病斑，边缘暗褐中间灰白。', '合理密植，控制氮肥；喷施井冈霉素。', 'images/2.jpg'),
                                                                                (1, '二化螟', '幼虫蛀食茎秆，分蘖期造成枯鞘、枯心苗。', '安装杀虫灯；喷施阿维菌素。', 'images/3.jpg'),
                                                                                (1, '稻飞虱', '成虫、若虫群集稻丛基部刺吸汁液，导致植株变黄。', '选用吡虫啉、烯啶虫胺、吡蚜酮。', 'images/4.jpg'),
                                                                                (1, '水稻恶苗病', '病株细高，叶片淡黄，节间拉长。', '严格进行种子消毒（咪鲜胺浸种）。', 'images/5.jpg'),
                                                                                (2, '小麦赤霉病', '穗部颖壳出现水浸状腐烂，产生粉红色霉层。', '抽穗扬花期喷施多菌灵、氰烯菌酯。', 'images/6.jpg'),
                                                                                (2, '小麦锈病', '叶片上产生鲜黄色条状粉堆。', '选用三唑酮、戊唑醇喷雾。', 'images/7.jpg'),
                                                                                (2, '小麦蚜虫', '群集于叶片、茎秆和穗部吸食汁液。', '吡虫啉、啶虫脒、抗蚜威喷雾。', 'images/8.jpg'),
                                                                                (2, '小麦全蚀病', '根部变黑腐烂，地上部出现白穗。', '硅噻菌胺拌种；轮作倒茬。', 'images/9.jpg'),
                                                                                (3, '玉米大斑病', '叶片出现长梭形青灰色或褐色大斑。', '喷施百菌清、多菌灵。', 'images/10.jpg'),
                                                                                (3, '玉米螟', '幼虫钻蛀茎秆和果穗，造成折茎。', '心叶末期撒施辛硫磷颗粒剂。', 'images/11.jpg'),
                                                                                (3, '玉米丝黑穗病', '果穗变成黑粉包，内部混有丝状物。', '戊唑醇、烯唑醇拌种。', 'images/12.jpg'),
                                                                                (3, '草地贪夜蛾', '幼虫暴食叶片，钻蛀心叶和果穗。', '甲维盐、氯虫苯甲酰胺喷雾。', 'images/13.jpg'),
                                                                                (4, '棉铃虫', '幼虫蛀食蕾、花、铃，造成落蕾、落铃。', '种植Bt抗虫棉；喷施高效氯氟氰菊酯。', 'images/14.jpg'),
                                                                                (4, '棉花枯萎病', '维管束变褐，叶片网状褪绿或变黄。', '选用抗病品种；恶霉灵灌根。', 'images/15.jpg'),
                                                                                (4, '棉红蜘蛛', '叶片出现黄白斑点，后变红褐色。', '阿维菌素、哒螨灵喷雾。', 'images/16.jpg'),
                                                                                (5, '大豆食心虫', '幼虫蛀入豆荚咬食豆粒，造成虫食粒。', '敌敌畏熏蒸；菊酯类农药喷雾。', 'images/17.jpg'),
                                                                                (5, '大豆胞囊线虫病', '植株矮黄，根系产生大量小颗粒胞囊。', '轮作（与禾本科）；种衣剂包衣。', 'images/18.jpg'),
                                                                                (5, '高粱丝黑穗病', '全穗变成黑粉包，内部有黑色丝状物。', '戊唑醇拌种；轮作。', 'images/19.jpg'),
                                                                                (5, '花生叶斑病', '叶片出现褐色或黑色斑点，严重时脱落。', '百菌清、多菌灵喷雾。', 'images/20.jpg');